def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_d = sum(1 for x in my if x == 'D')
    opp_d = sum(1 for x in opp if x == 'D')
    opp_c = n - opp_d
    last_me = my[-1]
    last_opp = opp[-1]

    # Endgame: defect on the last round, and on the second-to-last if opponent never defected or just defected
    if n >= 99:
        return 'D'
    if n == 98:
        if opp_d == 0:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # If opponent has never cooperated, always defect
    if opp_c == 0:
        return 'D'

    # Probe and exploit phase
    if opp_d == 0:
        if my_d == 0:
            if n == 1:
                return 'D'  # probe
            return 'C'
        else:
            if n == 2:
                return 'C'  # test round after probe
            return 'D'  # exploit

    # Normal mode: forgiving tit-for-tat
    if last_opp == 'D':
        if last_me == 'D':
            if opp_d <= 2 or opp_d * 2 < n:
                return 'C'
            return 'D'
        else:
            if opp_d <= 2 or opp_d * 4 < n:
                return 'C'
            return 'D'
    else:
        return 'C'
